// Generates the tracked block of docs/IMPLEMENTATION_STATUS.md from canonical sources.
// Deterministic: the output depends only on repository content (no wall-clock time), so CI can
// regenerate it and fail when the committed file is stale.
import { TICKET_STATUS_LABEL } from '../lib/project.mjs';

export const BEGIN =
  '<!-- devtrack:begin (generated by `pnpm devtrack status --write`; edit the sources, not this block) -->';
export const END = '<!-- devtrack:end -->';

const esc = (s) =>
  String(s ?? '')
    .replace(/\|/g, '\\|')
    .replace(/\n/g, ' ');

export function renderStatusBlock(project, workstreams) {
  const { tickets, acceptance, decisions, evidence, sessions, derived } = project;
  const latest = [...evidence.map((e) => e.recordedAt), ...project.devlog.map((d) => String(d.recordedAt))]
    .filter(Boolean)
    .sort()
    .at(-1);
  const current = sessions.at(-1);
  const t = derived.ticketStatusCounts;
  const a = derived.acceptanceStatusCounts;
  const d = derived.decisionStatusCounts;
  const fmtCounts = (obj, order, labels = {}) =>
    order
      .filter((k) => obj[k])
      .map((k) => `${obj[k]} ${labels[k] ?? k}`)
      .join(' · ') || 'none';
  const lines = [];
  lines.push(BEGIN, '');
  lines.push(`_Source state as of ${latest ?? 'n/a'} · version ${project.version}._`, '');
  lines.push('### Summary', '');
  lines.push('| Measure | Value |', '|---|---|');
  lines.push(
    `| Current session | ${esc(`${current.id}: ${current.title}`)} (${current.status}) on \`${current.branch}\` |`,
  );
  lines.push(
    `| Kit tickets (${tickets.length}) | ${fmtCounts(t, ['done', 'in_progress', 'ready', 'blocked', 'planned'], TICKET_STATUS_LABEL)} |`,
  );
  lines.push(
    `| Acceptance scenarios (${acceptance.length}) | ${fmtCounts(a, ['PASS', 'FAIL', 'BLOCKED', 'UNRUN'])} |`,
  );
  lines.push(
    `| Founder decisions (${decisions.length}) | ${fmtCounts(d, ['Decided', 'Discussing', 'Deferred', 'Proposed'])} |`,
  );
  lines.push(
    `| Engineering estimate | ${derived.hours.low}–${derived.hours.high} h + ${derived.hours.reserve} h reserve = ${derived.hours.totalLow}–${derived.hours.totalHigh} h |`,
  );
  lines.push(
    `| Critical path (low / high) | ${derived.criticalPath.low.hours} h / ${derived.criticalPath.high.hours} h: ${derived.criticalPath.high.path.join(' → ')} |`,
  );
  lines.push(`| Evidence records | ${evidence.length} |`, '');

  lines.push('### Kit tickets', '');
  lines.push('| Ticket | Title | Status | Hours | Depends on | Evidence |', '|---|---|---|---|---|---|');
  for (const tk of tickets) {
    const ev = (project.evidenceBySubject.get(tk.id) ?? []).map((e) => e.id).join(', ') || '—';
    lines.push(
      `| ${tk.id} | ${esc(tk.title)} | ${TICKET_STATUS_LABEL[tk.status] ?? tk.status} | ${tk.hoursLow}–${tk.hoursHigh} | ${tk.dependencies.join(', ') || '—'} | ${ev} |`,
    );
  }
  lines.push('');

  lines.push('### Enabling workstreams', '');
  lines.push('| Workstream | Title | Status | Evidence |', '|---|---|---|---|');
  for (const w of workstreams) {
    const ev = (project.evidenceBySubject.get(w.id) ?? []).map((e) => e.id).join(', ') || '—';
    lines.push(`| ${w.id} | ${esc(w.title)} | ${w.status.replace('_', ' ')} | ${ev} |`);
  }
  lines.push('');

  const ran = acceptance.filter((x) => x.status !== 'UNRUN');
  lines.push('### Acceptance scenarios', '');
  lines.push(
    ran.length
      ? `${ran.length} of ${acceptance.length} have a recorded status other than UNRUN:`
      : `All ${acceptance.length} scenarios in docs/ACCEPTANCE_TESTS.md are UNRUN. No application exists yet.`,
  );
  for (const x of ran) lines.push(`- ${x.id} ${x.status}: ${esc(x.scenario)}`);
  lines.push('');

  lines.push('### Evidence log', '');
  lines.push(
    '| ID | Recorded | Session | Subjects | Kind | Result | Summary |',
    '|---|---|---|---|---|---|---|',
  );
  for (const e of [...evidence].reverse())
    lines.push(
      `| ${e.id} | ${e.recordedAt} | ${e.session} | ${e.subjects.join(', ')} | ${e.kind} | ${e.result} | ${esc(e.summary)} |`,
    );
  lines.push('', END);
  return lines.join('\n');
}

export function replaceBlock(document, block) {
  const start = document.indexOf('<!-- devtrack:begin');
  const end = document.indexOf(END);
  if (start === -1 || end === -1) throw new Error('IMPLEMENTATION_STATUS.md: devtrack markers not found');
  return document.slice(0, start) + block + document.slice(end + END.length);
}
